CREATE DATABASE ecole;
USE ecole;
DROP DATABASE ecole;

UPDATE eleve
SET moyenne = 16.00
WHERE id = 1;

-- 1. Sélectionner toutes les colonnes d'une table :
SELECT * FROM eleve;

-- 2. Projection de colonnes spécifiques avec alias (AS) :
SELECT nom, prenom, moyenne AS note_finale FROM eleve;

-- 3. Élimination des doublons avec DISTINCT :
SELECT DISTINCT ville FROM eleve;

-- 4. Calculs d'expressions dans SELECT :
SELECT nom, prix, prix * 1.19 AS prix_ttc FROM produit;

-- 1. Filtre numérique et comparaison :
SELECT * FROM eleve WHERE moyenne >= 10;

-- 2. Filtre textuel et masques (LIKE) :
SELECT * FROM eleve WHERE nom LIKE 'A%';

-- 3. Combinaison logique (AND / OR) et intervalle :
SELECT * FROM eleve WHERE section = 'SI' AND moyenne BETWEEN 12 AND 18;

-- 4. Test de nullité (IS NULL / IS NOT NULL) :
SELECT * FROM eleve WHERE email IS NOT NULL;

-- 1. Tri croissant simple (par défaut ASC) :
SELECT * FROM eleve ORDER BY nom ASC;

-- 2. Tri décroissant par moyenne :
SELECT nom, moyenne FROM eleve ORDER BY moyenne DESC;

-- 3. Tri multicritères (par section croissant, puis par moyenne décroissant) :
SELECT nom, section, moyenne
FROM eleve
ORDER BY section ASC, moyenne DESC;

-- Élèves ayant une moyenne supérieure à la moyenne générale :
SELECT nom, moyenne FROM eleve
WHERE moyenne > (SELECT AVG(moyenne) FROM eleve);

-- Élèves appartenant à certaines classes :
SELECT nom FROM eleve
WHERE id_classe IN (SELECT id_classe FROM classe WHERE niveau = '4ème');

-- Compter le nombre total d'élèves de la section SI :
SELECT COUNT(*) FROM eleve WHERE section = 'SI';

-- Compter uniquement les élèves ayant renseigné un email (exclut les NULL) :
SELECT COUNT(email) FROM eleve;

-- Compter le nombre de villes différentes (uniques) :
SELECT COUNT(DISTINCT ville) FROM eleve;
